def _cart_position(event, item, membership=None, **kwargs):
    return CartPosition(
        event=event, item=item, price=Decimal('23.00'), used_membership=membership, **kwargs
    )


@pytest.fixture
def limited_membership_type(event):
    return event.organizer.membership_types.create(name="Limited", max_usages=1)


@pytest.fixture
def limited_ticket(event, limited_membership_type):
    i = Item.objects.create(
        event=event, name='Limited ticket', default_price=Decimal('23.00'), admission=True,
        require_membership=True,
    )
    i.require_membership_types.add(limited_membership_type)
    return i


@pytest.mark.django_db
def test_validate_memberships_no_requirement(event, customer):
    cp = _cart_position(event, Item.objects.create(event=event, name='Ticket', default_price=Decimal('23.00')))
    validate_memberships_in_order(None, [cp], event, testmode=False)


@pytest.mark.django_db
def test_validate_memberships_valid(event, customer, membership, requiring_ticket):
    cp = _cart_position(event, requiring_ticket, membership)
    validate_memberships_in_order(customer, [cp], event, lock=True, testmode=False)


@pytest.mark.django_db
def test_validate_memberships_no_customer(event, requiring_ticket):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(None, [_cart_position(event, requiring_ticket)], event)


@pytest.mark.django_db
def test_validate_memberships_none_selected(event, customer, requiring_ticket):
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket)], event)


