@pytest.mark.django_db
def test_validate_memberships_expired_for_event(event, customer, membership, requiring_ticket):
    membership.date_start -= timedelta(days=100)
    membership.date_end -= timedelta(days=100)
    membership.save()
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [_cart_position(event, requiring_ticket, membership)], event)


@pytest.mark.django_db
def test_validate_memberships_not_yet_started_with_valid_from_not_chosen(event, customer, membership, requiring_ticket):
    membership.date_start = datetime(2021, 5, 1, 0, 0, 0, 0, tzinfo=TZ)
    membership.date_end = now() + timedelta(days=365)
    membership.save()
    cp = _cart_position(event, requiring_ticket, membership)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [cp], event)
    validate_memberships_in_order(customer, [cp], event, valid_from_not_chosen=True)


@pytest.mark.django_db
def test_validate_memberships_usages_exhausted(event, customer, limited_membership_type, limited_ticket):
    m = customer.memberships.create(
        membership_type=limited_membership_type,
        date_start=datetime(2021, 4, 1, 0, 0, 0, 0, tzinfo=TZ),
        date_end=datetime(2021, 4, 30, 23, 59, 59, 999999, tzinfo=TZ),
    )
    order = event.orders.create(
        code='ABC', status=Order.STATUS_PENDING, email='dummy@example.org', customer=customer,
        datetime=now(), expires=now() + timedelta(days=1), total=Decimal('23.00'),
        sales_channel=event.organizer.sales_channels.get(identifier='web'),
    )
    order.positions.create(item=limited_ticket, price=Decimal('23.00'), used_membership=m, positionid=1)

    cp = _cart_position(event, limited_ticket, m)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [cp], event)
    # The order that already uses the membership is exempt when it is being changed
    validate_memberships_in_order(customer, [cp], event, ignored_order=order)


@pytest.mark.django_db
def test_validate_memberships_usages_within_batch(event, customer, limited_membership_type, limited_ticket):
    m = customer.memberships.create(
        membership_type=limited_membership_type,
        date_start=datetime(2021, 4, 1, 0, 0, 0, 0, tzinfo=TZ),
        date_end=datetime(2021, 4, 30, 23, 59, 59, 999999, tzinfo=TZ),
    )
    cp1 = _cart_position(event, limited_ticket, m)
    cp2 = _cart_position(event, limited_ticket, m)
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [cp1, cp2], event)
    validate_memberships_in_order(customer, [cp1], event)


@pytest.mark.django_db
def test_validate_memberships_variation_overrides_item(event, customer, membership, membership_type, requiring_ticket):
    other_type = event.organizer.membership_types.create(name="Other")
    other_membership = customer.memberships.create(
        membership_type=other_type,
        date_start=membership.date_start,
        date_end=membership.date_end,
    )
    variation = requiring_ticket.variations.create(value="Gold")
    variation.require_membership = True
    variation.save()
    variation.require_membership_types.add(other_type)
    cp = _cart_position(event, requiring_ticket, other_membership, variation=variation)
    validate_memberships_in_order(customer, [cp], event)
    cp.used_membership = membership
    with pytest.raises(ValidationError):
        validate_memberships_in_order(customer, [cp], event)
